// Объект в фигурных скобках: ключ: значение
const user = {
  name: "Анна",
  age: 25,
  city: "Москва"
};

// Доступ через точку: пользователь.ключ
console.log(user.name);   // Анна
console.log(user.age);    // 25
console.log(user.city);   // Москва

// Ключи — строки (кавычки можно писать, можно не писать):
const user2 = {
  "name": "Борис",     // с кавычками
  age: 30              // без кавычек — тоже работает
};
console.log(user2.name);  // Борис

const config = {
  theme: "dark",
  fontSize: 14
};

// Точка — просто и читаемо:
console.log(config.theme);     // dark

// Скобки — когда ключ из переменной (динамический):
const key = "fontSize";
console.log(config[key]);      // 14 — config["fontSize"] = config.fontSize

// Скобки нужны, когда ключ содержит пробел или спецсимвол:
const obj = {
  "first-name": "Ann"
};
console.log(obj["first-name"]);  // Ann — через точку не получится!

const car = { brand: "Toyota", year: 2020 };

// Изменить существующий:
car.year = 2023;
console.log(car.year);  // 2023

// Добавить новый:
car.color = "red";
console.log(car);       // { brand: "Toyota", year: 2023, color: "red" }

// Удалить:
delete car.color;
console.log(car);       // { brand: "Toyota", year: 2023 }

// Проверить, есть ли свойство:
console.log("brand" in car);  // true
console.log("color" in car);  // false — удалён

// Примитивы — копируются по ЗНАЧЕНИЮ:
let a = 10;
let b = a;  // b = 10 (копия)
b = 20;     // b стал 20
console.log(a);  // 10 — a НЕ изменился

// Объекты — копируются по ССЫЛКЕ:
let obj1 = { x: 10 };
let obj2 = obj1;  // obj2 = ссылку на ТОТ ЖЕ объект
obj2.x = 20;      // меняем через obj2
console.log(obj1.x);  // 20 — obj1 тоже изменился!
// Потому что obj1 и obj2 — один и тот же объект в памяти

