// Опасная ситуация:
let user;
// user = { name: "Ann" };

// user undefined — обращение к свойству = TypeError!
// console.log(user.name);  // TypeError!

// Безопасный вариант — optional chaining:
console.log(user?.name);  // undefined — без ошибки!

// Второй вариант — проверка перед обращением:
if (user) {
  console.log(user.name);
}

const user = {
  name: "Анна",
  address: {
    city: "Москва",
    zip: "123456"
  }
};

// Доступ через цепочку точек:
console.log(user.address.city);  // Москва

// Optional chaining — безопасно:
console.log(user?.address?.city);   // Москва
console.log(user?.phone?.number);   // undefined — нет ошибки!

// Без optional chaining (опасно):
// console.log(user.phone.number);  // TypeError — user.phone undefined

const user = { name: "Ann", age: 25, city: "MSK" };

// for...in — по ключам:
for (const key in user) {
  console.log(key + ": " + user[key]);
  // name: Ann, age: 25, city: MSK
}

// Object.keys — массив ключей:
console.log(Object.keys(user));  // ["name", "age", "city"]

// Object.values — массив значений:
console.log(Object.values(user));  // ["Ann", 25, "MSK"]

// Object.entries — пары [ключ, значение]:
for (const [key, value] of Object.entries(user)) {
  console.log(key, value);
}

